const menu=document.querySelector('.menu'),navigation=document.querySelector('#navigation');
function closeMenu(){menu.setAttribute('aria-expanded','false');navigation.classList.remove('open')}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));navigation.classList.toggle('open',open)});
navigation.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
const projects={memorybook:{title:'MemoryBook',image:'memorybook',description:'Un espacio para crear álbumes de fotos, personalizar sus páginas y construir recuerdos con otras personas. Un proyecto que une edición visual, colaboración y el encanto de un libro de fotografías.',tags:['React','Editor visual','Colaboración'],url:null},filmlab:{title:'FilmLab',image:'filmlab',description:'Un proyecto nacido de mi interés por la fotografía. Una experiencia de edición pensada para experimentar con ajustes, tonos y estilos desde el celular.',tags:['Fotografía','Color','Experiencia móvil'],repo:'film-lab',url:'https://film-lab-joy.vercel.app/'},professional:{title:'FilmLab Professional',image:'filmlab-pro',description:'La exploración de un editor fotográfico de escritorio, con máscaras y ajustes de color. Una interfaz que busca dar más espacio a la imagen y acercar herramientas de edición a un flujo creativo.',tags:['Edición','Máscaras','Interfaz de escritorio'],repo:'Film-Lab-Professional'},bimu:{title:'Bimu',image:'bimu',description:'Música, archivos y herramientas cotidianas en un pequeño compañero que vive en el borde de tu pantalla.',tags:['Escritorio','Interacción','Música','Productividad'],repo:'Bimu'},soundlify:{title:'Soundlify',image:'soundlify',description:'Un dashboard conectado con Spotify para explorar artistas y canciones destacados en distintos períodos. Presenta un perfil del oyente, características de sus gustos y una distribución de géneros musicales.',tags:['Spotify','Dashboard','Perfil musical'],repo:'soundlify',url:'https://soundlify.vercel.app'}};
projects.memorybook.caseStudy={"subtitle":"Recuerdos que se construyen juntos","sections":[{"title":"La idea","paragraphs":["MemoryBook nació mientras planeaba un viaje. Quería reunir las fotos que trajera de esa experiencia en un álbum propio, diseñado para convertirse en un libro físico. Un lugar donde los recuerdos pudieran seguir viviendo más allá de la pantalla."]},{"title":"La experiencia","paragraphs":["Un viaje compartido también deja recuerdos repartidos entre distintas cámaras y celulares. Reunir esas fotos y diseñar un álbum desde una sola computadora puede convertir un proceso creativo en una tarea lenta y difícil de coordinar.","La propuesta de MemoryBook es que cada persona pueda aportar su mirada y participar en la creación del mismo álbum desde su propio dispositivo."]},{"title":"Mi trabajo","paragraphs":["Desarrollé el editor visual para organizar fotografías, personalizar textos y componer páginas a partir de distintos diseños. También trabajé en los permisos de acceso y edición, y en la adaptación de la interfaz a celulares para facilitar la participación desde diferentes dispositivos."]},{"title":"El desafío","paragraphs":["El principal desafío fue equilibrar la libertad de diseño con una experiencia de colaboración clara. Dar espacio para crear, sin perder de vista quién puede editar el álbum y cómo mantener las herramientas cómodas de usar en cada pantalla."]},{"title":"El resultado","paragraphs":["MemoryBook reúne edición visual, personalización y colaboración en una experiencia pensada para construir álbumes con identidad propia. Un proyecto en evolución que busca transformar fotografías dispersas en una historia compartida, con la intención de llevarla también al papel."]}]};
projects.filmlab.caseStudy={"subtitle":"Una mirada propia para cada fotografía","sections":[{"title":"La idea","paragraphs":["FilmLab nace de mi interés por la fotografía y de las ganas de explorar cómo el color, la luz y la textura pueden transformar una imagen. Quería crear una herramienta propia para experimentar con distintos estilos y encontrar una estética que se sintiera personal."]},{"title":"La experiencia","paragraphs":["La propuesta es poder probar, comparar y ajustar una fotografía desde una interfaz cómoda para el celular. Acercar las herramientas de edición al proceso creativo, para descubrir distintas versiones de una misma imagen."]},{"title":"Mi trabajo","paragraphs":["Desarrollé la interfaz de edición y sus controles de luz, color, textura y efectos, junto con la aplicación de filtros y la comparación con la fotografía original. Trabajé especialmente en la organización de las herramientas y en la experiencia de uso desde pantallas pequeñas."]},{"title":"El desafío","paragraphs":["Encontrar un equilibrio entre las posibilidades de edición y la claridad de la interfaz. Dar acceso a distintos ajustes sin que los controles le quiten protagonismo a la fotografía."]},{"title":"El resultado","paragraphs":["FilmLab es un espacio de experimentación fotográfica que reúne mis intereses por el desarrollo y la imagen. Un proyecto en evolución donde cada herramienta parte de una búsqueda personal: tener más libertad para construir una mirada propia."]}]};
projects.professional.caseStudy={"subtitle":"Más capacidad para explorar cada imagen","sections":[{"title":"La idea","paragraphs":["FilmLab Professional surge de la misma inquietud que dio origen a FilmLab, pero con una necesidad adicional: trabajar con imágenes de mayor calidad y desarrollar un motor de procesamiento más potente para acompañar esa exigencia.","Mi interés por la fotografía me llevó a explorar cómo ampliar las posibilidades del editor, tanto en la capacidad de procesamiento como en el control sobre cada ajuste."]},{"title":"La experiencia","paragraphs":["La versión Professional propone un espacio de trabajo pensado para escritorio, con más lugar para observar la imagen y realizar una edición detallada. Las máscaras permiten trabajar sobre zonas específicas y combinar ajustes dentro de una misma fotografía."]},{"title":"Mi trabajo","paragraphs":["Desarrollé la interfaz de escritorio y las herramientas de edición global y por máscaras, trabajando en la interacción con sus controles y guías sobre la imagen. El proyecto también aborda la evolución del motor de procesamiento para trabajar con archivos más exigentes."]},{"title":"El desafío","paragraphs":["Avanzar hacia una mayor capacidad de procesamiento manteniendo una interacción fluida. Combinar imágenes de mayor calidad, ajustes y máscaras plantea un desafío técnico que acompaña el desarrollo de la versión Professional."]},{"title":"El resultado","paragraphs":["FilmLab Professional es una evolución del proyecto hacia una edición más precisa y exigente. Un espacio donde profundizo en el procesamiento de imágenes y en el diseño de herramientas que acompañen mi forma de explorar la fotografía."]}]};
projects.bimu.caseStudy={"subtitle": "Un pequeño compañero para tu escritorio", "sections": [{"title": "La idea", "paragraphs": ["Bimu nace de la búsqueda de un espacio propio dentro del escritorio: pequeño, accesible y con personalidad. Un lugar donde reunir herramientas cotidianas y tenerlas a mano sin interrumpir lo que estoy haciendo."]}, {"title": "La experiencia", "paragraphs": ["Un notch integrado al borde superior muestra la hora, indicadores del sistema y unos ojos que acompañan el movimiento del cursor. Al acercarse, se despliega para controlar la música, seguir sus letras, acceder a archivos, consultar el clima o iniciar un modo de trabajo."]}, {"title": "Mi trabajo", "paragraphs": ["Desarrollé la aplicación de escritorio y sus interfaces, integrando las herramientas con los estados compactos y desplegados del notch. Trabajé especialmente en las animaciones, la navegación, la personalización visual y los detalles de interacción que le dan a Bimu una presencia propia."]}, {"title": "El desafío", "paragraphs": ["Hacer que Bimu esté disponible sin volverse una distracción. Equilibrar información, controles y personalidad dentro de un espacio reducido, cuidando cuándo se despliega, cómo cambia de tamaño y cómo convive con otras aplicaciones."]}, {"title": "El resultado", "paragraphs": ["Una aplicación que reúne música, archivos, atajos e información cotidiana en una experiencia compacta y personalizable. Su evolución también implicó simplificar: dejar atrás el enfoque de agente con IA y transformar las funciones más útiles en controles directos."]}]};
projects.soundlify.caseStudy={"subtitle":"Descubrir lo que cuenta tu música","sections":[{"title":"La idea","paragraphs":["Soundlify parte de una curiosidad: qué podemos descubrir sobre nuestros gustos al observar la música que escuchamos. Quería transformar los datos de Spotify en una experiencia que permitiera explorar hábitos, reconocer preferencias y encontrar conexiones entre artistas, canciones y géneros."]},{"title":"La experiencia","paragraphs":["La propuesta es recorrer un resumen personal de escucha y compararlo en distintos períodos. Artistas y canciones destacados, distribución de géneros y un perfil musical reúnen distintas formas de mirar una actividad tan cotidiana como escuchar música."]},{"title":"Mi trabajo","paragraphs":["Desarrollé el dashboard y la integración con Spotify para presentar la información de escucha en una interfaz organizada. Trabajé en la selección de períodos, las tarjetas de contenido y la visualización de géneros y características del perfil musical.","El foco estuvo en convertir los datos en una lectura clara, con una jerarquía visual que ayudara a descubrirlos."]},{"title":"El desafío","paragraphs":["Dar sentido a la información más allá de mostrar un listado de resultados. Organizar distintas señales de escucha y presentarlas como una experiencia comprensible, sin perder el vínculo entre los datos y lo que representan.","También fue importante distinguir las estadísticas de las interpretaciones del perfil, que funcionan como una lectura orientativa de los gustos musicales."]},{"title":"El resultado","paragraphs":["Soundlify convierte la actividad de escucha en un recorrido visual por los gustos de cada persona. Un proyecto que combina integración de datos y diseño de interfaces para descubrir nuevas formas de conectar con la música que nos acompaña."]}]};
// Cards and modal share one project configuration; links only appear with a known URL.
document.querySelectorAll('.project').forEach(card=>{
 const trigger=card.querySelector('[data-project]');const project=projects[trigger.dataset.project];
 const target=(card.matches('.film-pro')?card.querySelector('.project-copy>div'):card.querySelector('.numbered-copy>div'))||card.querySelector('.project-copy');
 const actions=document.createElement('div');actions.className='project-actions';
 const details=document.createElement('button');details.className='project-details';details.type='button';details.textContent='Ver proyecto';details.addEventListener('click',()=>openProject(trigger.dataset.project,details));actions.append(details);
 if(project.url){const link=document.createElement('a');link.className='project-web';link.href=project.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Ver en la web ↗';link.setAttribute('aria-label',`Ver ${project.title} en la web`);actions.append(link)}
 target.append(actions);
});
const dialog=document.querySelector('#project-dialog'),scroller=document.querySelector('#modal-scroll');let previousFocus;
function openProject(key,trigger){const p=projects[key];previousFocus=trigger;
 document.querySelector('#dialog-title').textContent=p.title;
 const image=document.querySelector('#dialog-image');image.src=`assets/${p.image}-real.webp`;image.alt=`Captura real de ${p.title}`;image.classList.toggle('mobile-capture',key==='filmlab');
 const description=document.querySelector('#dialog-description');description.textContent=p.caseStudy?p.caseStudy.subtitle:p.description;description.classList.toggle('case-study-intro',Boolean(p.caseStudy));
 const story=document.querySelector('#dialog-case-study');story.replaceChildren();story.hidden=!p.caseStudy;
 if(p.caseStudy){story.replaceChildren(...p.caseStudy.sections.map((section,index)=>{const block=document.createElement('section');block.className='case-section';const number=document.createElement('span');number.className='case-number';number.textContent=String(index+1).padStart(2,'0');number.setAttribute('aria-hidden','true');const body=document.createElement('div');const heading=document.createElement('h3');heading.textContent=section.title;body.append(heading);for(const text of section.paragraphs){const paragraph=document.createElement('p');paragraph.textContent=text;body.append(paragraph)}block.append(number,body);return block}))}
 document.querySelector('.concept-note').hidden=Boolean(p.caseStudy);
 document.querySelector('#dialog-tags').replaceChildren(...p.tags.map(t=>{const el=document.createElement('span');el.textContent=t;return el}));
 const repo=document.querySelector('#repo-link');repo.hidden=!p.repo;if(p.repo)repo.href=`https://github.com/marianoarias1/${p.repo}`;
 const web=document.querySelector('#web-link');web.hidden=!p.url;if(p.url)web.href=p.url;
 dialog.showModal();document.body.style.overflow='hidden';scroller.scrollTop=0;requestAnimationFrame(layoutScrollbar);
}
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>openProject(button.dataset.project,button)));
document.querySelector('.close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
dialog.addEventListener('close',()=>{document.body.style.overflow='';previousFocus?.focus({preventScroll:true})});
// The native content scroller drives a curved SVG track, including its rounded ends.
const rail=document.querySelector('#curved-scrollbar'),track=rail.querySelector('.scroll-rail'),handle=rail.querySelector('.scroll-handle'),hit=rail.querySelector('.scroll-hit');
let railLength=0,handleLength=0,scrollFrame=0,dragging=false,dragOffset=0;
function updateScrollbar(){scrollFrame=0;const max=scroller.scrollHeight-scroller.clientHeight;const progress=max>0?scroller.scrollTop/max:0;handle.style.strokeDasharray=`${handleLength} ${railLength+1}`;handle.style.strokeDashoffset=String(-progress*(railLength-handleLength));rail.setAttribute('aria-valuenow',String(Math.round(progress*100)))}
function layoutScrollbar(){if(!dialog.open)return;const h=scroller.clientHeight;rail.setAttribute('viewBox',`0 0 64 ${h}`);const radius=Math.min(15,h/8);const d=`M ${50-radius} 13 Q 50 13 50 ${radius+13} L 50 ${h-radius-13} Q 50 ${h-13} ${50-radius} ${h-13}`;for(const path of [track,handle,hit])path.setAttribute('d',d);railLength=track.getTotalLength();const ratio=scroller.clientHeight/scroller.scrollHeight;handleLength=Math.min(railLength,Math.max(46,railLength*ratio));const active=scroller.scrollHeight>scroller.clientHeight+2;rail.classList.toggle('is-hidden',!active);rail.setAttribute('aria-disabled',String(!active));rail.tabIndex=active?0:-1;updateScrollbar()}
scroller.addEventListener('scroll',()=>{if(!scrollFrame)scrollFrame=requestAnimationFrame(updateScrollbar)},{passive:true});
new ResizeObserver(layoutScrollbar).observe(scroller);new ResizeObserver(layoutScrollbar).observe(document.querySelector('.dialog-flow'));document.querySelector('#dialog-image').addEventListener('load',layoutScrollbar);
function nearestDistance(event){const bounds=rail.getBoundingClientRect();const x=(event.clientX-bounds.left)*64/bounds.width,y=(event.clientY-bounds.top)*scroller.clientHeight/bounds.height;let best=Infinity,distance=0;for(let i=0;i<=160;i++){const d=railLength*i/160,p=track.getPointAtLength(d),delta=(p.x-x)**2+(p.y-y)**2;if(delta<best){best=delta;distance=d}}return distance}
function scrollToDistance(distance){const travel=railLength-handleLength;if(travel<=0)return;scroller.scrollTop=Math.max(0,Math.min(1,distance/travel))*(scroller.scrollHeight-scroller.clientHeight)}
rail.addEventListener('pointerdown',event=>{if(rail.classList.contains('is-hidden'))return;event.preventDefault();rail.focus({preventScroll:true});const distance=nearestDistance(event),max=scroller.scrollHeight-scroller.clientHeight,current=max>0?scroller.scrollTop/max*(railLength-handleLength):0;dragOffset=distance>=current&&distance<=current+handleLength?distance-current:handleLength/2;dragging=true;rail.setPointerCapture(event.pointerId);rail.classList.add('is-dragging');scrollToDistance(distance-dragOffset)});
rail.addEventListener('pointermove',event=>{if(dragging)scrollToDistance(nearestDistance(event)-dragOffset)});
function release(){dragging=false;rail.classList.remove('is-dragging')}
rail.addEventListener('pointerup',release);rail.addEventListener('pointercancel',release);rail.addEventListener('lostpointercapture',release);
rail.addEventListener('keydown',event=>{let next=scroller.scrollTop;const page=scroller.clientHeight*.85;if(event.key==='ArrowDown')next+=45;else if(event.key==='ArrowUp')next-=45;else if(event.key==='PageDown'||event.key===' ')next+=page;else if(event.key==='PageUp')next-=page;else if(event.key==='Home')next=0;else if(event.key==='End')next=scroller.scrollHeight;else return;event.preventDefault();scroller.scrollTop=next});
// Reveal once when a project enters the viewport; reduced-motion stays fully visible.
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');
if(!reducedMotion.matches&&'IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){entry.target.classList.remove('reveal-pending');observer.unobserve(entry.target)}}},{threshold:.08,rootMargin:'0px 0px -25px 0px'});document.querySelectorAll('.project').forEach(card=>{card.classList.add('reveal-pending');observer.observe(card)});reducedMotion.addEventListener('change',event=>{if(event.matches){document.querySelectorAll('.reveal-pending').forEach(card=>card.classList.remove('reveal-pending'));observer.disconnect()}})}
